<?php use App\Core\Http; $btn = function ($act, $id, $label) use ($canManage) { return $canManage ? '<form method="post" action="/admin/affiliates" style="display:inline">' . Http::csrfField() . '<input type="hidden" name="action" value="' . $act . '"><input type="hidden" name="id" value="' . (int) $id . '"><button class="ghost" type="submit">' . $label . '</button></form>' : ''; }; ?>
<h1>Affiliates</h1>
<table><tr><th>Name</th><th>Email</th><th>Status</th><th>Code</th><th></th></tr><?php foreach ($rows as $r): ?><tr><td><?= Http::e($r['name']) ?></td><td><?= Http::e($r['email']) ?></td><td><?= Http::e($r['status']) ?></td><td><?= Http::e($r['code'] ?? '') ?></td><td><?= $r['status'] === 'pending' ? $btn('approve_aff', $r['id'], 'Approve') . $btn('reject_aff', $r['id'], 'Reject') : '' ?></td></tr><?php endforeach; ?></table>
<h2>Commissions</h2><table><tr><th>#</th><th>Affiliate</th><th>Base</th><th>Amount</th><th>Status</th><th></th></tr><?php foreach ($commissions as $c): ?><tr><td><?= (int) $c['id'] ?></td><td><?= Http::e($c['email']) ?></td><td><?= number_format($c['base_cents'] / 100, 2) ?></td><td><?= number_format($c['amount_cents'] / 100, 2) ?></td><td><?= Http::e($c['status']) ?></td><td><?= in_array($c['status'], ['pending'], true) ? $btn('approve_com', $c['id'], 'Approve') : '' ?><?= in_array($c['status'], ['pending', 'approved'], true) ? $btn('reject_com', $c['id'], 'Reject') : '' ?></td></tr><?php endforeach; ?></table>
<h2>Payout requests</h2><table><tr><th>#</th><th>Affiliate</th><th>Amount</th><th>Status</th><th></th></tr><?php foreach ($payouts as $p): ?><tr><td><?= (int) $p['id'] ?></td><td><?= Http::e($p['email']) ?></td><td><?= number_format($p['amount_cents'] / 100, 2) ?></td><td><?= Http::e($p['status']) ?></td><td><?= $p['status'] === 'requested' ? $btn('pay', $p['id'], 'Mark paid') : '' ?></td></tr><?php endforeach; ?></table>
